package hu.synostream.android;
import org.junit.Test;import static org.junit.Assert.*;import java.util.*;
public class QuickFallbackTest {
 @Test public void emptyResolverForSingleWordHostShowsLocalRoute()throws Exception{List<String> tried=new ArrayList<>();NasClient c=new NasClient(new NasClient.Credentials("diskstation","","user","password",""),id->List.of(),endpoint->{tried.add(endpoint);return true;});c.connect();assertEquals("Helyi kapcsolat",c.route);assertNotEquals("QuickConnect",c.route);assertEquals(List.of("https://diskstation"),tried);}
 @Test public void resolvedRelayStillShowsQuickConnect()throws Exception{String endpoint="https://fixture.europe.quickconnect.to";NasClient c=new NasClient(new NasClient.Credentials("fixture","","user","password",""),id->List.of(endpoint),value->{assertEquals(endpoint,value);return true;});c.connect();assertEquals("QuickConnect",c.route);}
 @Test public void directEndpointKindReflectsPrivateHostIpOrDdns(){assertEquals(NasRoutes.Kind.LOCAL,NasClient.directKind("http://diskstation"));assertEquals(NasRoutes.Kind.LOCAL,NasClient.directKind("http://192.168.1.2"));assertEquals(NasRoutes.Kind.DIRECT,NasClient.directKind("http://192.0.2.2"));assertEquals(NasRoutes.Kind.DIRECT,NasClient.directKind("https://[2001:db8::1]"));assertEquals(NasRoutes.Kind.DDNS,NasClient.directKind("http://nas.example.org"));}
 @Test public void httpRemainsAcceptedForLocalDdnsAndPublicIp(){NasClient.Credentials c=new NasClient.Credentials("http://192.0.2.2:5000","http://192.168.1.2:5000","http://nas.example.org:5000","","user","password","");List<NasRoutes.Route> plan=NasRoutes.plan(c,true);assertEquals(3,plan.size());for(NasRoutes.Route route:plan)assertTrue(route.value.startsWith("http://"));assertEquals("http://nas.example.org:5000",NasClient.normalizeAddress("http://nas.example.org:5000"));}
}
